import tarfile, json, re
base='/Users/yangke/Personal/omen/orbit/docs/reference/evidence/codex-lessons-20261009'

def read(tar, suffix):
    with tarfile.open(tar,'r:gz') as t:
        for m in t.getmembers():
            if m.name.endswith(suffix):
                return t.extractfile(m).read()
    return b''

# K3: search native-model-calls and check prompt for the routing error and tool args
raw=read(f'{base}/positive-k3-fallback.tar.gz','native-model-calls.json')
text=raw.decode('utf-8','replace')
print('k3 native-model-calls bytes', len(text))
# find glm-5.2 and task tool snippets
for pat in ['glm-5.2', 'outside the available', '@task', 'Unknown eval', 'Delegating importer']:
    print(pat, text.lower().count(pat.lower()) if pat!='@task' else text.count(pat))

# parse if json
try:
    data=json.loads(text)
except Exception as e:
    print('not json', e)
    data=None
print('type', type(data).__name__, 'len', len(data) if hasattr(data,'__len__') else None)

def walk(obj, path=''):
    if isinstance(obj, dict):
        # tool call like
        name=obj.get('name') or obj.get('tool') or obj.get('toolName')
        if name in ('task','hub','eval') or (isinstance(name,str) and 'task'==name):
            args=obj.get('arguments') or obj.get('input') or obj.get('args')
            yield path, name, args, {k:obj.get(k) for k in ('id','tool_call_id','ok','error') if k in obj}
        for k,v in obj.items():
            yield from walk(v, path+'.'+k)
    elif isinstance(obj, list):
        for i,v in enumerate(obj[:]):
            yield from walk(v, f'{path}[{i}]')

if isinstance(data, (dict,list)):
    hits=list(walk(data))
    print('tool hits', len(hits))
    for path,name,args,meta in hits[:12]:
        s=json.dumps(args, ensure_ascii=False)[:600] if not isinstance(args,str) else args[:600]
        print('\n', name, meta, path[-80:])
        print(s[:500])
