function sandboxProfile(root, allowed) {
  const string = value => JSON.stringify(value);
  const libraries = ['/usr', '/System', '/Library', '/bin', '/sbin', '/opt'];
  if (root.includes('\\')) throw new Error('this command sandbox cannot safely express a backslash in the workspace path');
  const escapedRoot = root.replace(/[.*+?^${}()|[\]]/g, character =>
    character === '[' ? '[[]' : character === ']' ? '[]]' : `[${character}]`);
  const privateDescendants = `^${escapedRoot}/(.*/)?[.](git|orbit)(/.*)?$`;
  // dyld and getcwd need directory traversal. Literal ancestor directories
  // grant no access to the file contents of their other descendants.
  const directories = new Set();
  for (const target of [root, ...allowed, ...libraries, '/dev/null']) {
    let directory = path.dirname(target);
    for (;;) {
      directories.add(directory);
      const parent = path.dirname(directory);
      if (parent === directory) break;
      directory = parent;
    }
  }
  return ['(version 1)', '(deny default)', '(allow process*)', '(allow sysctl-read)',
    '(allow file-read-metadata)', '(allow mach-lookup)',
    `(allow file-read-data ${[...directories].map(base => `(literal ${string(base)})`).join(' ')})`,
    `(allow file-read-data ${[...allowed, ...libraries].map(base => `(subpath ${string(base)})`).join(' ')} (literal "/dev/null") (literal "/dev/urandom") (literal "/dev/random"))`,
    `(allow file-write* ${allowed.map(base => `(subpath ${string(base)})`).join(' ')})`,
    `(deny file-read* (subpath ${string(path.join(root, '.orbit'))}) (subpath ${string(path.join(root, '.git'))}))`,
    `(deny file-write* (subpath ${string(path.join(root, '.orbit'))}) (subpath ${string(path.join(root, '.git'))}))`,
    `(deny file-read* file-write* (regex #${string(privateDescendants)}))`,
    '(allow file-write-data (literal "/dev/null"))'].join('\n');
}

function availableSandbox() {
  if (sandboxReady !== undefined) return sandboxReady;
  if (process.platform !== 'darwin') return (sandboxReady = false);
  const probe = spawnSync('/usr/bin/sandbox-exec', ['-p', '(version 1) (deny default) (allow process*) (allow file-read*)',
    '/bin/sh', '-c', ':'], { timeout: 5000, encoding: 'utf8' });
  return (sandboxReady = probe.status === 0);
}

const SANDBOX_READ_ROOTS = ['/usr', '/System', '/Library', '/bin', '/sbin', '/opt'];
const SANDBOX_READ_FILES = new Set(['/dev/null', '/dev/urandom', '/dev/random']);
// Bare words only. Assignments, quotes and shell syntax are not parsed; a
// declared PATH= recovery command is left for the member shell.
const SHELL_SYNTAX = /[|&;<>`$(){}\\!#*?'"=\n[\]]/;
const RUNTIME_TOOLS = new Set(['node', 'npm', 'npx']);

function bareCommandExecutable(command) {
  if (typeof command !== 'string' || SHELL_SYNTAX.test(command)) return undefined;
  const token = command.trim().split(/[ \t]+/)[0];
  if (!token || token.startsWith('-') || token.includes('\0') || token.includes('..')) return undefined;
  return token;
}

function sandboxCanRead(realPath, allowed) {
  return SANDBOX_READ_FILES.has(realPath) ||
    [...allowed, ...SANDBOX_READ_ROOTS].some(base => within(base, realPath));
}

function commandRecovery(root, command, detail) {
  return `command ${JSON.stringify(command)} ${detail}. Do not redispatch it and do not count a Root-only rerun as the member result. ` +
    `Copy the current Node binary and npm package into ${root}/.runtime (a real copy, no credentials, user cache, or symlink back outside), ` +
    `add .runtime to allowed_paths, and declare PATH=${root}/.runtime/bin:$PATH npm test`;
}

// Static first-hop only: resolve one bare executable and its real path. Never
// spawns the declared command and does not follow package scripts or caches.
async function assertCommandReadable(command, root, allowed) {
  const token = bareCommandExecutable(command);
  if (!token) return;
  const pathEnv = process.env.PATH || '/usr/bin:/bin';
  const candidates = token.includes('/')
    ? [path.resolve(root, token)]
    : pathEnv.split(path.delimiter).filter(Boolean).map(dir => path.join(dir, token));
  for (const candidate of candidates) {
    let stat;
    try { stat = await fs.stat(candidate); }
    catch (error) {
      if (error?.code === 'EACCES') throw new Error(commandRecovery(root, command, `cannot read ${candidate}`));
      continue;
    }
    if (!stat.isFile()) continue;
    try { await fs.access(candidate, fileConstants.R_OK); }
    catch { throw new Error(commandRecovery(root, command, `cannot read ${candidate}`)); }
    const real = await fs.realpath(candidate);
    if (!sandboxCanRead(real, allowed))
      throw new Error(commandRecovery(root, command, `resolves ${token} to ${real}, outside the member sandbox read set`));
    return;
  }
  if (RUNTIME_TOOLS.has(token))
    throw new Error(commandRecovery(root, command, `has no readable ${token} on the member PATH`));
}

