const item = (requirement, extra = {}) => ({ requirement, status: "unverified", evidence: "", ...extra });
const cases = [];
const add = (name, result) => {
  const problems = validateCheckResult(JSON.parse(JSON.stringify(result)));
  cases.push({ name, ts: problems.length === 0, problems, json: JSON.stringify(result) });
};
add("nbsp-requirement", withCov([item("\u00A0")]));
add("nul-requirement", withCov([item("\u0000")]));
add("nbsp-verified-evidence", withCov([item("req", { status: "verified", evidence: "\u00A0" })]));
add("nul-verified-evidence", withCov([item("req", { status: "verified", evidence: "\u0000" })]));
add("dup-nbsp-suffix", withCov([item("req"), item("req\u00A0")]));
add("dup-nul-wrap", withCov([item("a"), item("\u0000a\u0000")]));
add("dup-ascii-space", withCov([item(" req "), item("req")]));
add("emoji-1000", withCov([item("🎯".repeat(600) + "x".repeat(400))]));
add("emoji-1001", withCov([item("🎯".repeat(600) + "x".repeat(401))]));
add("evidence-emoji-1000", withCov([item("req", { evidence: "🎯".repeat(1000) })]));
add("evidence-emoji-1001", withCov([item("req", { evidence: "🎯".repeat(1001) })]));
add("nbsp-1000", withCov([item("\u00A0".repeat(1000))]));
add("missing-scope", withCov([item("req")]));
add("scope-lifecycle", withCov([item("req", { scope: "lifecycle" })]));
add("ascii-verified-blank", withCov([item("req", { status: "verified", evidence: "  " })]));
add("unverified-empty-evidence", withCov([item("req", { evidence: "" })]));
add("reason-space", { ...base(), reason: " " });
add("finding-space", { ...base(), findings: [{ id: " ", requirement: " ", evidence: " ", action: " " }] });
add("items-64", withCov(Array.from({ length: 64 }, (_, i) => item("r" + i))));
add("items-65", withCov(Array.from({ length: 65 }, (_, i) => item("r" + i))));
const modelFloat = JSON.parse("{\"verdict\":\"continue\",\"reason\":\"r\",\"findings\":[],\"resolved_ids\":[],\"next_check_seconds\":1.0,\"delivery\":{\"ready\":false,\"reason\":\"x\"}}");
add("float-through-js", modelFloat);
const samples = JSON.parse(await Bun.file("tests/fixtures/check-result-samples.json").text());
for (const sample of samples.samples) add("fixture:" + sample.name, sample.result);
console.log(JSON.stringify(cases));
')
