require "orbit/check_runner"
runner = Orbit::CheckRunner.new(model: "probe", executable: "/usr/bin/true")
rules = Orbit::CheckRunner.result_structure
cases = JSON.parse(ENV.fetch("PAYLOAD"))
splits = []
agree = []
cases.each do |c|
  value = JSON.parse(c["json"])
  problems = runner.send(:result_problems, rules, value)
  rb = problems.empty?
  if rb == c["ts"]
    agree << c["name"]
  else
    splits << { name: c["name"], ts: c["ts"], ruby: rb, ts_problems: c["problems"], ruby_problems: problems }
  end
end
direct = JSON.parse("{\"verdict\":\"continue\",\"reason\":\"r\",\"findings\":[],\"resolved_ids\":[],\"next_check_seconds\":1.0,\"delivery\":{\"ready\":false,\"reason\":\"x\"}}")
direct_problems = runner.send(:result_problems, rules, direct)
puts JSON.pretty_generate({
  agree: agree,
  splits: splits,
  ruby_direct_float: { accept: direct_problems.empty?, problems: direct_problems, klass: direct["next_check_seconds"].class.to_s },
  strip: {
    nbsp: "\u00A0".strip.empty?,
    nul: "\u0000".strip.empty?,
    nbsp_suffix: "req\u00A0".strip,
    nul_wrap: "\u0000a\u0000".strip
  }
})
' PAYLOAD="$payload"

