bun -e '
const cps = [];
for (let i = 0; i <= 0x2FFF; i++) cps.push(i);
for (let i = 0x3000; i <= 0x3010; i++) cps.push(i);
cps.push(0xFEFF, 0x1F600, 0x180E, 0x0085, 0x200B, 0x2060);
const rows = cps.map(cp => {
  const s = String.fromCodePoint(cp);
  const t = s.trim();
  return [cp, s.length, [...s].length, t === "" ? 1 : 0, t];
});
// also edge compositions
const extra = ["\u00A0a", "a\u00A0", "\u00A0a\u00A0", "\u0000", "\u0000a\u0000", "\u3000", " \u3000 ", "\u2028", "\uFEFF", "\u000B", "\u001C", "\u180E", "\u0085", "\u200B"];
const extras = extra.map(s => [s, [...s].length, s.trim()]);
await Bun.write("/dev/stdout", JSON.stringify({ rows, extras }));
' > /tmp/c08-trim-js.json
ruby -rjson -Ilib -e '
require "orbit/check_runner"
runner = Orbit::CheckRunner.new(model: "probe", executable: "/usr/bin/true")
data = JSON.parse(File.read("/tmp/c08-trim-js.json"))
bad = []
data["rows"].each do |cp, js_units, js_points, js_blank, js_trim|
  s = [cp].pack("U")
  rb = runner.send(:trim_coverage_text, s)
  rb_blank = rb.empty? ? 1 : 0
  if rb_blank != js_blank || s.length != js_points
    bad << { cp: cp, js_blank: js_blank, rb_blank: rb_blank, rb_len: s.length, js_points: js_points, js_units: js_units }
  end
end
extra_bad = []
data["extras"].each do |s, js_points, js_trim|
  rb = runner.send(:trim_coverage_text, s)
  extra_bad << { s: s.codepoints, js: js_trim.codepoints, rb: rb.codepoints } if rb != js_trim
end
# lone surrogate through JSON text
js_surv = JSON.parse(File.read("/tmp/c08-trim-js.json")) # placeholder
puts JSON.generate({ mismatches: bad.first(30), mismatch_count: bad.size, extra_bad: extra_bad })
'
